"""Parse and evaluate mathematical expressions with correct operator precedence.

Grammar (recursive descent):
    expression = term (('+' | '-') term)*
    term       = exponent (('*' | '/') exponent)*
    exponent   = unary ('^' exponent)?          # right-associative
    unary      = ('-' | '+')? atom
    atom       = NUMBER | '(' expression ')'
"""

from __future__ import annotations


class _Parser:
    """Internal recursive-descent parser."""

    def __init__(self, expr: str) -> None:
        self.expr = expr
        self.pos = 0
        self.length = len(expr)

    # -- helpers -----------------------------------------------------------

    def _skip_ws(self) -> None:
        while self.pos < self.length and self.expr[self.pos] == " ":
            self.pos += 1

    def _peek(self) -> str | None:
        self._skip_ws()
        return self.expr[self.pos] if self.pos < self.length else None

    def _consume(self) -> str:
        self._skip_ws()
        ch = self.expr[self.pos]
        self.pos += 1
        return ch

    def _expect(self, ch: str) -> None:
        self._skip_ws()
        if self.pos >= self.length or self.expr[self.pos] != ch:
            raise SyntaxError(
                f"Expected '{ch}' at position {self.pos}, "
                f"got '{self.expr[self.pos] if self.pos < self.length else 'EOF'}'"
            )
        self.pos += 1

    # -- grammar rules -----------------------------------------------------

    def parse(self) -> float:
        result = self._expression()
        self._skip_ws()
        if self.pos != self.length:
            raise SyntaxError(
                f"Unexpected character '{self.expr[self.pos]}' at position {self.pos}"
            )
        return result

    def _expression(self) -> float:
        """expression = term (('+' | '-') term)*"""
        left = self._term()
        while self._peek() in ("+", "-"):
            op = self._consume()
            right = self._term()
            left = left + right if op == "+" else left - right
        return left

    def _term(self) -> float:
        """term = exponent (('*' | '/') exponent)*"""
        left = self._exponent()
        while self._peek() in ("*", "/"):
            op = self._consume()
            right = self._exponent()
            if op == "*":
                left *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left /= right
        return left

    def _exponent(self) -> float:
        """exponent = unary ('^' exponent)?   (right-associative)"""
        base = self._unary()
        if self._peek() == "^":
            self._consume()
            exponent = self._exponent()  # recurse for right-associativity
            return base ** exponent
        return base

    def _unary(self) -> float:
        """unary = ('-' | '+')? atom"""
        if self._peek() == "-":
            self._consume()
            return -self._atom()
        if self._peek() == "+":
            self._consume()
            return self._atom()
        return self._atom()

    def _atom(self) -> float:
        """atom = NUMBER | '(' expression ')'"""
        self._skip_ws()
        ch = self._peek()
        if ch is None:
            raise SyntaxError("Unexpected end of expression")

        if ch == "(":
            self._consume()  # '('
            val = self._expression()
            self._expect(")")
            return val

        # NUMBER: integer or decimal
        start = self.pos
        has_dot = False
        while self.pos < self.length:
            c = self.expr[self.pos]
            if c.isdigit():
                self.pos += 1
            elif c == "." and not has_dot:
                has_dot = True
                self.pos += 1
            else:
                break
        if self.pos == start:
            raise SyntaxError(
                f"Expected number or '(' at position {self.pos}, got '{self.expr[self.pos]}'"
            )
        return float(self.expr[start : self.pos])


def throttle_function(expr: str) -> float:
    """Evaluate a mathematical expression string with standard operator precedence.

    Supported operators (highest to lowest precedence):
        ^        exponentiation (right-associative)
        - +      unary prefix
        * /      multiplication, division
        + -      addition, subtraction

    Grouping with parentheses is supported.

    Args:
        expr: The mathematical expression to evaluate.

    Returns:
        The numeric result as a float.

    Raises:
        SyntaxError: On malformed expressions.
        ZeroDivisionError: On division by zero.

    Examples:
        >>> throttle_function("2 + 3 * 4")
        14.0
        >>> throttle_function("(2 + 3) * 4")
        20.0
        >>> throttle_function("2 ^ 3 ^ 2")
        512.0
    """
    if not expr or not expr.strip():
        raise ValueError("Expression must not be empty")
    return _Parser(expr.strip()).parse()


