import unittest


class TestThrottleFunction(unittest.TestCase):
    """Comprehensive tests for the expression parser."""

    # -- basic arithmetic --------------------------------------------------

    def test_single_number(self):
        self.assertEqual(throttle_function("42"), 42.0)

    def test_decimal_number(self):
        self.assertAlmostEqual(throttle_function("3.14"), 3.14)

    def test_addition(self):
        self.assertAlmostEqual(throttle_function("1 + 2"), 3.0)

    def test_subtraction(self):
        self.assertAlmostEqual(throttle_function("10 - 3"), 7.0)

    def test_multiplication(self):
        self.assertAlmostEqual(throttle_function("4 * 5"), 20.0)

    def test_division(self):
        self.assertAlmostEqual(throttle_function("15 / 3"), 5.0)

    def test_float_division(self):
        self.assertAlmostEqual(throttle_function("7 / 2"), 3.5)

    def test_exponentiation(self):
        self.assertAlmostEqual(throttle_function("2 ^ 10"), 1024.0)

    # -- operator precedence -----------------------------------------------

    def test_multiply_before_add(self):
        # 2 + 3 * 4 = 2 + 12 = 14
        self.assertAlmostEqual(throttle_function("2 + 3 * 4"), 14.0)

    def test_divide_before_subtract(self):
        # 10 - 6 / 3 = 10 - 2 = 8
        self.assertAlmostEqual(throttle_function("10 - 6 / 3"), 8.0)

    def test_exponent_before_multiply(self):
        # 3 * 2 ^ 3 = 3 * 8 = 24
        self.assertAlmostEqual(throttle_function("3 * 2 ^ 3"), 24.0)

    def test_left_to_right_multiplication(self):
        # 2 * 3 * 4 = 24
        self.assertAlmostEqual(throttle_function("2 * 3 * 4"), 24.0)

    def test_left_to_right_addition(self):
        # 1 + 2 + 3 = 6
        self.assertAlmostEqual(throttle_function("1 + 2 + 3"), 6.0)

    def test_mixed_precedence_chain(self):
        # 1 + 2 * 3 - 4 / 2 = 1 + 6 - 2 = 5
        self.assertAlmostEqual(throttle_function("1 + 2 * 3 - 4 / 2"), 5.0)

    def test_complex_precedence(self):
        # 2 + 3 * 4 ^ 2 - 1 = 2 + 3*16 - 1 = 2 + 48 - 1 = 49
        self.assertAlmostEqual(throttle_function("2 + 3 * 4 ^ 2 - 1"), 49.0)

    # -- exponentiation associativity (right) ------------------------------

    def test_exponent_right_associative(self):
        # 2 ^ 3 ^ 2 = 2 ^ (3 ^ 2) = 2 ^ 9 = 512
        self.assertAlmostEqual(throttle_function("2 ^ 3 ^ 2"), 512.0)

    def test_exponent_right_associative_chain(self):
        # 2 ^ 2 ^ 2 ^ 2 = 2 ^ (2 ^ (2 ^ 2)) = 2 ^ 16 = 65536
        self.assertAlmostEqual(throttle_function("2 ^ 2 ^ 2 ^ 2"), 65536.0)

    # -- parentheses -------------------------------------------------------

    def test_simple_parens(self):
        # (2 + 3) * 4 = 20
        self.assertAlmostEqual(throttle_function("(2 + 3) * 4"), 20.0)

    def test_nested_parens(self):
        # ((2 + 3) * (4 + 1)) = 25
        self.assertAlmostEqual(throttle_function("(2 + 3) * (4 + 1)"), 25.0)

    def test_deeply_nested_parens(self):
        # ((((1 + 1)))) = 2
        self.assertAlmostEqual(throttle_function("((((1 + 1))))"), 2.0)

    def test_parens_override_precedence(self):
        # 2 * (3 + 4) = 14  vs  2 * 3 + 4 = 10
        self.assertAlmostEqual(throttle_function("2 * (3 + 4)"), 14.0)

    def test_parens_in_exponent(self):
        # 2 ^ (1 + 1) = 4
        self.assertAlmostEqual(throttle_function("2 ^ (1 + 1)"), 4.0)

    # -- unary operators ---------------------------------------------------

    def test_unary_minus(self):
        self.assertAlmostEqual(throttle_function("-5"), -5.0)

    def test_unary_plus(self):
        self.assertAlmostEqual(throttle_function("+5"), 5.0)

    def test_unary_minus_in_expression(self):
        # 3 + -2 = 1
        self.assertAlmostEqual(throttle_function("3 + -2"), 1.0)

    def test_double_unary_minus(self):
        # - -5 = 5
        self.assertAlmostEqual(throttle_function("- -5"), 5.0)

    def test_unary_minus_before_exponent(self):
        # -2 ^ 2 = -(2^2) = -4
        self.assertAlmostEqual(throttle_function("-2 ^ 2"), -4.0)

    def test_unary_minus_with_parens(self):
        # -(3 + 4) = -7
        self.assertAlmostEqual(throttle_function("-(3 + 4)"), -7.0)

    # -- whitespace --------------------------------------------------------

    def test_no_whitespace(self):
        self.assertAlmostEqual(throttle_function("2+3*4"), 14.0)

    def test_extra_whitespace(self):
        self.assertAlmostEqual(throttle_function("  2   +   3  *  4  "), 14.0)

    def test_tabs(self):
        self.assertAlmostEqual(throttle_function("2\t+\t3"), 5.0)

    # -- edge cases --------------------------------------------------------

    def test_zero(self):
        self.assertAlmostEqual(throttle_function("0"), 0.0)

    def test_zero_operations(self):
        self.assertAlmostEqual(throttle_function("0 * 999"), 0.0)
        self.assertAlmostEqual(throttle_function("0 + 0"), 0.0)

    def test_large_numbers(self):
        self.assertAlmostEqual(throttle_function("999999 * 999999"), 999999.0 ** 2)

    def test_small_decimals(self):
        self.assertAlmostEqual(throttle_function("0.1 + 0.2"), 0.3, places=10)

    def test_complex_expression(self):
        # (2 + 3) * 4 ^ 2 / (1 + 1) - 7 = 5 * 16 / 2 - 7 = 40 - 7 = 33
        self.assertAlmostEqual(
            throttle_function("(2 + 3) * 4 ^ 2 / (1 + 1) - 7"), 33.0
        )

    def test_expression_with_all_operators(self):
        # 1 + 2 - 3 * 4 / 2 ^ 2 = 1 + 2 - 3*4/4 = 1 + 2 - 3 = 0
        self.assertAlmostEqual(
            throttle_function("1 + 2 - 3 * 4 / 2 ^ 2"), 0.0
        )

    # -- error cases -------------------------------------------------------

    def test_empty_expression(self):
        with self.assertRaises(ValueError):
            throttle_function("")

    def test_whitespace_only(self):
        with self.assertRaises(ValueError):
            throttle_function("   ")

    def test_missing_operand(self):
        with self.assertRaises(SyntaxError):
            throttle_function("2 +")

    def test_missing_operator(self):
        with self.assertRaises(SyntaxError):
            throttle_function("2 3")

    def test_unmatched_open_paren(self):
        with self.assertRaises(SyntaxError):
            throttle_function("(2 + 3")

    def test_unmatched_close_paren(self):
        with self.assertRaises(SyntaxError):
            throttle_function("2 + 3)")

    def test_empty_parens(self):
        with self.assertRaises(SyntaxError):
            throttle_function("()")

    def test_double_operator(self):
        with self.assertRaises(SyntaxError):
            throttle_function("2 + * 3")

    def test_invalid_character(self):
        with self.assertRaises(SyntaxError):
            throttle_function("2 & 3")

    def test_division_by_zero(self):
        with self.assertRaises(ZeroDivisionError):
            throttle_function("1 / 0")

    def test_trailing_operator(self):
        with self.assertRaises(SyntaxError):
            throttle_function("2 + 3 *")

    # -- return type -------------------------------------------------------

    def test_returns_float(self):
        self.assertIsInstance(throttle_function("1 + 2"), float)

    def test_integer_input_returns_float(self):
        self.assertIsInstance(throttle_function("42"), float)


if __name__ == "__main__":
    unittest.main()

